#include <stdio.h>
#include <string.h>
#include <errno.h>

void test_opendir_func(void)
{
    DIR *dir = opendir("/SD:/");
    TEST_ASSERT_NOT_NULL(dir);
    closedir(dir);
}

void test_readdir_func(void)
{
    DIR *dir = opendir("/SD:/");
    TEST_ASSERT_NOT_NULL(dir);
    struct dirent *entry = readdir(dir);
    TEST_ASSERT_NOT_NULL(entry);
    closedir(dir);
}

void test_loop_readdir_not_infinite(void)
{
    DIR *dir = opendir("/SD:/");
    TEST_ASSERT_NOT_NULL(dir);
    struct dirent *entry = readdir(dir);
    int count = 0;
    while (entry != NULL && count < 64) {
        printf("d_name: %s, d_type: %d\n", entry->d_name, entry->d_type);
        count++;
        entry = readdir(dir);
    }
    if (count == 64) {
        printf("[WARN] Too many entries or possible infinite loop!\n");
        TEST_FAIL();
    }
    closedir(dir);
}

void test_closedir_func(void)
{
    DIR *dir = opendir("/SD:/");
    TEST_ASSERT_NOT_NULL(dir);
    closedir(dir);
}

